// @ts-nocheck
const self = this;

return (async () => {
  const items = $input.all();

  const parsedData = items.find(item => item.json.isValid);
  if (!parsedData?.json) {
    throw new Error('No valid parsed email data found.');
  }

  const input = parsedData.json;
  const webhookData = items.find(item => item.json.emailUid);
  const emailUid = webhookData?.json?.emailUid || 'unknown';

  console.log('📊 ===== CHECK DAILY LIMIT (GLOBAL) START =====');

  const projectId = 'join-angular-based';
  const baseUrl = `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents`;

  // === GLOBALER COUNT (nicht pro User!) ===
  const today = new Date().toISOString().split('T')[0];
  const docId = `global_${today}`;  // ← GEÄNDERT: global statt email-basiert
  const limitDocPath = `daily_limits/${docId}`;

  console.log('📂 Document Path:', limitDocPath);

  let currentCount = 0;
  const maxDaily = 10;

  try {
    const getUrl = `${baseUrl}/${limitDocPath}`;
    const getResponse = await self.helpers.httpRequest({
      method: 'GET',
      url: getUrl,
      headers: { 'Content-Type': 'application/json' },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });

    if (getResponse.statusCode === 200) {
      const doc = getResponse.body;
      currentCount = parseInt(doc.fields?.count?.integerValue || '0');
      console.log('✅ Current GLOBAL count:', currentCount);
    } else if (getResponse.statusCode === 404) {
      console.log('📝 No document yet, starting at 0');
    }

    const newCount = currentCount + 1;
    console.log(`📊 Count: ${currentCount} → ${newCount} / ${maxDaily}`);

    const limitExceeded = newCount > maxDaily;

    if (limitExceeded) {
      console.log('❌ GLOBAL LIMIT EXCEEDED!');
      return {
        json: {
          ...input,
          emailUid: emailUid,
          limitExceeded: true,
          currentCount: currentCount,
          dailyLimit: maxDaily,
          remainingRequests: 0,
          message: `Daily limit of ${maxDaily} requests exceeded.`
        }
      };
    }

    // Count hochzählen
    const updateBody = {
      fields: {
        date: { stringValue: today },
        count: { integerValue: String(newCount) },
        lastUpdated: { timestampValue: new Date().toISOString() },
        lastRequestTitle: { stringValue: String(input.title || 'untitled').substring(0, 100) }
      }
    };

    const patchResponse = await self.helpers.httpRequest({
      method: 'PATCH',
      url: getUrl,
      headers: { 'Content-Type': 'application/json' },
      body: updateBody,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      json: true
    });

    if (patchResponse.statusCode === 200) {
      console.log(`✅ GLOBAL count updated: ${newCount} / ${maxDaily}`);
    }

    return {
      json: {
        ...input,
        emailUid: emailUid,
        limitExceeded: false,
        currentCount: newCount,
        dailyLimit: maxDaily,
        remainingRequests: maxDaily - newCount
      }
    };

  } catch (error) {
    console.error('🔴 Error:', error.message);
    return {
      json: {
        ...input,
        emailUid: emailUid,
        limitExceeded: false,
        currentCount: 0,
        dailyLimit: maxDaily,
        remainingRequests: maxDaily,
        _error: error.message
      }
    };
  }
})();

// Node Name: Prepare Firebase Document
// Language: JavaScript

const req = $input.first().json;

console.log('📦 Preparing Firebase document...');
console.log('Input data:', JSON.stringify(req, null, 2));
console.log('🤖 Subtasks from AI:', req.subtasks?.length || 0);
console.log('📊 Current Count:', req.currentCount, '/', req.dailyLimit);

// === VALIDATE INPUT DATA ===
if (!req) {
  throw new Error('No data received from Check Daily Limit node');
}

if (!req.type) {
  throw new Error('Missing required field: type. Received: ' + JSON.stringify(req));
}

if (!req.title) {
  throw new Error('Missing required field: title');
}

if (!req.description) {
  throw new Error('Missing required field: description');
}

if (!req.userEmail) {
  throw new Error('Missing required field: userEmail');
}

// === CATEGORY MAPPING ===
const categoryMap = {
  'feature': 'User Story',
  'bug': 'Technical Task',
  'question': 'User Story',
  'improvement': 'User Story'
};
const reqType = String(req.type || 'feature').toLowerCase();
const category = categoryMap[reqType] || 'User Story';

// === DUE DATE BERECHNEN ===
const priorityDaysMap = {
  'high': 3,
  'medium': 7,
  'low': 14
};

const reqPriority = String(req.priority || 'medium').toLowerCase();
const priority = ['high', 'medium', 'low'].includes(reqPriority) ? reqPriority : 'medium';
const daysToAdd = priorityDaysMap[priority];
const dueDate = new Date(Date.now() + daysToAdd * 24 * 60 * 60 * 1000);

console.log('📅 Priority:', priority, '→ Due in', daysToAdd, 'days');

// === DESCRIPTION ===
const description = String(req.description);

// === PREPARE SUBTASKS FOR FIRESTORE ===
const subtasks = req.subtasks || [];
const firestoreSubtasks = subtasks.map(function(st) {
  return {
    mapValue: {
      fields: {
        id: { stringValue: String(st.id) },
        title: { stringValue: String(st.title) },
        completed: { booleanValue: Boolean(st.completed) }
      }
    }
  };
});

console.log('✅ Firebase document prepared:', req.title.substring(0, 80));
console.log('🔍 Status set to:', req.status || 'triage');
console.log('📋 Subtasks to save:', subtasks.length);

if (subtasks.length > 0) {
  console.log('📝 Subtasks:');
  subtasks.forEach(function(st, i) {
    console.log('   ' + (i + 1) + '. ' + st.title);
  });
}

// === FIRESTORE REST API FORMAT ===
const firestoreBody = {
  fields: {
    title: { stringValue: String(req.title).substring(0, 80) },
    description: { stringValue: description },
    category: { stringValue: category },
    dueDate: { timestampValue: dueDate.toISOString() },
    priority: { stringValue: priority },
    status: { stringValue: String(req.status || 'triage') },
    createdAt: { timestampValue: new Date().toISOString() },
    updatedAt: { timestampValue: new Date().toISOString() },
    source: { stringValue: String(req.source || 'email') },
    creatorType: { stringValue: 'external' },
    creatorEmail: { stringValue: String(req.userEmail) },
    creatorName: { stringValue: String(req.userName || req.userEmail.split('@')[0]) },
    aiGenerated: { booleanValue: true },
    subtasks: { 
      arrayValue: { 
        values: firestoreSubtasks
      }
    },
    // NEU: Daily Limit Info speichern
    dailyLimitInfo: {
      mapValue: {
        fields: {
          currentCount: { integerValue: String(req.currentCount || 0) },
          dailyLimit: { integerValue: String(req.dailyLimit || 10) },
          remainingRequests: { integerValue: String(req.remainingRequests || 10) }
        }
      }
    }
  }
};

console.log('📊 Daily Limit Info added:', req.currentCount, '/', req.dailyLimit);

// === OUTPUT ===
return {
  json: firestoreBody
};

// Node Name: Parse & Validate Email
// Language: JavaScript

const input = $input.item.json;

console.log('📧 Processing Email Input');
console.log('=== COMPLETE INPUT ===');
console.log(JSON.stringify(input, null, 2));
console.log('=== END INPUT ===');

// === DETECT INPUT SOURCE ===
let webhookData = null;

if (input.body && typeof input.body === 'object' && !input.from && !input.subject) {
  webhookData = input.body;
  console.log('✅ Webhook data found in body property');
}

const hasWebhookFields = webhookData && webhookData.type && webhookData.title && webhookData.description && webhookData.userEmail;
const hasEmailFields = input.from || input.subject || input.text || input.textPlain || (typeof input.body === 'string');

let type, title, description, userEmail, userName, priority, status, timestamp, emailUid, originalFrom, originalSubject;

// ============================================================
// WEBHOOK INPUT (Direct from Frontend)
// ============================================================
if (hasWebhookFields) {
  console.log('✅ Processing WEBHOOK input');

  const data = webhookData;

  type = data.type || 'feature';
  title = data.title || 'Untitled Request';
  description = data.description || '';
  userEmail = data.userEmail || '';
  userName = data.userName || userEmail.split('@')[0];
  timestamp = data.timestamp || new Date().toISOString();
  emailUid = `webhook-${Date.now()}`;

  console.log('Extracted from webhook:');
  console.log('  type:', type);
  console.log('  title:', title);
  console.log('  userEmail:', userEmail);
  console.log('  userName:', userName);

  // KEINE VALIDIERUNG FÜR WEBHOOK
  console.log('✅ Webhook data accepted (no validation)');

  // Priority detection from description content
  const urgentKeywords = /urgent|dringend|sofort|kritisch|critical|security|high|asap|immediately/i;
  const lowKeywords = /low|niedrig|später|nice to have|nice-to-have|optional|someday/i;

  priority = 'medium';
  if (urgentKeywords.test(title) || urgentKeywords.test(description)) {
    priority = 'high';
  } else if (lowKeywords.test(title) || lowKeywords.test(description)) {
    priority = 'low';
  }

  status = 'triage';
  originalFrom = userEmail;
  originalSubject = `[${type}] ${title}`;
}

// ============================================================
// EMAIL/IMAP INPUT (From Email)
// ============================================================
else if (hasEmailFields) {
  console.log('✅ Processing EMAIL/IMAP input');

  const from = input.from?.address || input.from?.text || input.from || '';
  const subject = input.subject || '';

  let body = input.text 
    || input.textPlain 
    || (typeof input.body === 'string' ? input.body : '')
    || input.textAsHtml 
    || input.html
    || '';

  emailUid = input.uid || input.messageId || 'empty';
  originalFrom = from;
  originalSubject = subject;

  console.log('From:', from);
  console.log('Subject:', subject);

  const bodyStr = typeof body === 'string' ? body : String(body || '');
  const cleanBody = bodyStr.replace(/<[^>]*>/g, '');

  // === EXTRACT EMAIL AND NAME ===
  const emailMatch = from.match(/([^\s@]+@[^\s@]+\.[^\s@]+)/);
  userEmail = emailMatch ? emailMatch[1] : from;

  const nameMatch = from.match(/^([^<]+)</);
  userName = nameMatch ? nameMatch[1].trim().replace(/"/g, '') : userEmail.split('@')[0];

  // === EXTRACT TYPE ===
  const subjectTypeMatch = subject.match(/^\[(Feature|Bug|Question|Improvement)\]/i);

  if (subjectTypeMatch) {
    type = subjectTypeMatch[1].toLowerCase();
  } else {
    const bodyTypeMatch = cleanBody.match(/Type:\s*(Feature|Bug|Question|Improvement)/i);
    if (bodyTypeMatch) {
      type = bodyTypeMatch[1].toLowerCase();
    }
  }

  const validTypes = ['feature', 'bug', 'question', 'improvement'];
  type = validTypes.includes(type) ? type : 'feature';

  // === EXTRACT TITLE ===
  title = subject.replace(/^\[(Feature|Bug|Question|Improvement)\]\s*/i, '').trim();

  if (!title || title.length < 5) {
    const titleMatch = cleanBody.match(/Title:\s*(.+?)(?:\n|$)/i);
    title = titleMatch ? titleMatch[1].trim() : 'Untitled Request';
  }

  // === EXTRACT DESCRIPTION - NUR DIE ORIGINAL-ANFRAGE ===
  // Extrahiere nur den Text nach "## 📝 Original-Anfrage:" oder nehme den ganzen Body
  const originalRequestMatch = cleanBody.match(/##\s*📝\s*Original-Anfrage:\s*\n\s*(.+?)(?:\n\s*---|\n\s*\*\*Täglich|$)/is);

  if (originalRequestMatch) {
    description = originalRequestMatch[1].trim();
    console.log('✅ Extracted original request from email');
  } else {
    // Fallback: Nehme den ganzen Body ohne Metadaten
    description = cleanBody
      .replace(/\*\*Dieses Ticket wurde KI-generiert[\s\S]*?---/g, '')
      .replace(/\*\*Täglich[\s\S]*$/g, '')
      .replace(/💡\s*\*Dieser Stakeholder[\s\S]*$/g, '')
      .replace(/Type:.*?\n/gi, '')
      .replace(/Title:.*?\n/gi, '')
      .replace(/Priority:.*?\n/gi, '')
      .replace(/---[\s\S]*$/g, '')
      .trim();
  }

  console.log('Extracted Description:', description);

  // === DETECT PRIORITY ===
  const urgentKeywords = /urgent|dringend|sofort|kritisch|critical|security|high|asap|immediately/i;
  const lowKeywords = /low|niedrig|später|nice to have|nice-to-have|optional|someday/i;

  priority = 'medium';

  if (urgentKeywords.test(subject) || urgentKeywords.test(cleanBody)) {
    priority = 'high';
  } else if (lowKeywords.test(subject) || lowKeywords.test(cleanBody)) {
    priority = 'low';
  }

  status = 'triage';
  timestamp = input.date || new Date().toISOString();

  console.log('✅ Email processed successfully (no validation)');
}

// ============================================================
// UNKNOWN INPUT
// ============================================================
else {
  console.log('❌ Unknown input format');

  return {
    json: {
      isValid: false,
      reason: 'Unknown input format - expected either webhook or email data',
      availableFields: Object.keys(input)
    }
  };
}

// ============================================================
// RETURN DATA (No Validation - Always Valid)
// ============================================================
console.log('📋 Final data:', {
  type,
  title: title.substring(0, 80),
  userEmail,
  userName,
  priority,
  status,
  source: hasWebhookFields ? 'webhook' : 'email'
});

return {
  json: {
    isValid: true,
    reason: '',
    emailUid: emailUid,
    type: type,
    title: title.substring(0, 80),
    description: description,
    userEmail: userEmail,
    userName: userName,
    priority: priority,
    status: status,
    timestamp: timestamp,
    originalFrom: originalFrom,
    originalSubject: originalSubject,
    source: hasWebhookFields ? 'webhook' : 'email'
  }
};

// Node Name: Update Task ID from Firebase Response
// Language: JavaScript

const response = $input.first().json;

// Extract the auto-generated Firebase Document ID
const firebaseDocId = response.name.split('/').pop();

console.log('🔥 Firebase created document:', firebaseDocId);
console.log('📝 Updating task ID field to match...');

// Return data for PATCH request
return {
  json: {
    documentPath: response.name,
    documentId: firebaseDocId,
    patchUrl: `https://firestore.googleapis.com/v1/${response.name}?updateMask.fieldPaths=id`,
    patchBody: {
      fields: {
        id: { stringValue: firebaseDocId }
      }
    }
  }
};

const aiResponse = $input.first().json;
const validatedData = $('Is Limit Reached?').first().json;
const filteredData = $('Filter for KI').first().json;

let subtasks = [];
let taskDescription = '';
let generatedTitle = '';

try {
  let content = aiResponse.content?.parts?.[0]?.text || '';

  if (!content) {
    throw new Error('AI response text content is empty.');
  }

  console.log('📝 Raw Gemini Content:', content.substring(0, 500));

  // Entferne Markdown Code-Blöcke
  const codeBlockMatch = content.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  if (codeBlockMatch) {
    content = codeBlockMatch[1];
  }

  // Finde JSON-Objekt
  const jsonMatch = content.match(/\{[\s\S]*"subtasks"[\s\S]*\}/);

  if (!jsonMatch) {
    throw new Error('No JSON object with "subtasks" key found.');
  }

  const parsed = JSON.parse(jsonMatch[0]);

  // ✅ NEU: Extrahiere KI-generierten Titel
  if (parsed.title && typeof parsed.title === 'string') {
    generatedTitle = parsed.title.trim().substring(0, 80);
    console.log('🎯 AI Generated Title:', generatedTitle);
  }

  // Extrahiere Description (falls vorhanden)
  taskDescription = parsed.description || filteredData.description;

  // Validiere Subtasks
  if (!Array.isArray(parsed.subtasks)) {
    throw new Error('The "subtasks" key does not contain a valid array.');
  }

  // Formatiere Subtasks
  subtasks = parsed.subtasks.map(st => ({
    id: `subtask_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    title: String(st.title || st).trim().substring(0, 255),
    completed: false
  }));

  console.log('✅ AI Analysis Success - Title:', generatedTitle, 'Subtasks:', subtasks.length);

} catch (error) {
  console.error('🔴 Gemini parsing failed:', error.message);
  taskDescription = filteredData.description;
  subtasks = [];
  generatedTitle = '';
}

// ✅ Fallback: Wenn KI keinen Titel generiert, nutze Original
const finalTitle = generatedTitle || validatedData.title || 'Feature Request';

// Gib kombinierte Daten zurück
return {
  json: {
    ...validatedData,
    title: finalTitle,  // ← KI-generierter oder Original-Titel
    description: taskDescription,
    subtasks: subtasks,
    _aiGenerated: {
      title: !!generatedTitle,
      subtasks: subtasks.length > 0
    }
  }
};

// Node: Filter for KI
const input = $input.first().json;

console.log('🔍 ===== FILTER FOR KI START =====');
console.log('Original Description Length:', (input.description || '').length);
console.log('Original Description:', input.description);

// Bereinige die Description
let cleanedDescription = input.description || '';

// Entferne Grüße, Signaturen und überflüssige Zeilenumbrüche
cleanedDescription = cleanedDescription
  .replace(/^(Hi|Hello|Hey|Hallo|Guten Tag|Moin|Servus)[,!\s]*/gi, '')
  .replace(/\n*(VG|Grüße|Gruß|LG|MfG|Best|Regards|Cheers|Thanks|Danke)[,!\s]*$/gi, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

console.log('Cleaned Description Length:', cleanedDescription.length);
console.log('Cleaned Description:', cleanedDescription);

// WICHTIG: Mindestlänge prüfen
if (cleanedDescription.length < 10) {
  console.log('⚠️ WARNING: Description too short after cleaning!');
  cleanedDescription = input.description; // Fallback auf Original
}

console.log('🔍 ===== FILTER FOR KI END =====');

return {
  json: {
    type: input.type,
    title: input.title,
    description: cleanedDescription,
    originalDescription: input.description // Zur Sicherheit behalten
  }
};

